<?php $statusLabels = ['active' => 'Active', 'inactive' => 'Inactive', 'maintenance' => 'Maintenance']; $isEdit = $section === 'bays-edit'; ?>
<div class="customer-modal-backdrop" role="presentation"><section class="customer-modal bay-modal" role="dialog" aria-modal="true" aria-labelledby="bay-form-title"><div class="customer-modal-header"><div><span class="modal-eyebrow">Workshop setup</span><h2 id="bay-form-title"><?= $isEdit ? 'Edit Bay' : 'Add Bay' ?></h2><span class="modal-code"><?= $isEdit ? 'Update bay assignment and status' : 'Create a workshop bay and assign an employee' ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=bays" aria-label="Close">&times;</a></div><div class="customer-modal-body"><?php if ($errors): ?><div class="alert alert-danger"><?php foreach ($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="index.php?page=admin&amp;section=<?= e($section) ?>&amp;id=<?= (int) $id ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Bay Name / Number *</label><input class="form-control" name="bay_name" value="<?= e($input['bay_name']) ?>" placeholder="e.g. Bay 1" required></div><div class="col-md-6"><label class="form-label">Status *</label><select class="form-select" name="status" required><?php foreach ($statusLabels as $value => $label): ?><option value="<?= e($value) ?>" <?= $input['status'] === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Assign Employee / Mechanic</label><select class="form-select" name="assigned_employee_id"><option value="0">Not assigned</option><?php foreach ($options as $option): ?><option value="<?= (int) $option['id'] ?>" <?= $input['assigned_employee_id'] === (int) $option['id'] ? 'selected' : '' ?>><?= e($option['name'] . ' (' . $option['employee_code'] . ') - ' . $option['role_position']) ?></option><?php endforeach; ?></select><small class="bay-field-hint">One employee can be assigned to this bay. You can change the assignment later.</small></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3" placeholder="Optional bay notes"><?= e($input['notes']) ?></textarea></div></div><div class="customer-modal-footer px-0 pb-0"><a class="btn btn-light" href="index.php?page=admin&amp;section=bays">Cancel</a><button class="btn btn-primary" type="submit"><?= $isEdit ? 'Update Bay' : 'Save Bay' ?></button></div></form></div></section></div>
